	WR16(DS, D_DI_PRINT, POP16());	/* POP DI_PRINT */
	{ uint16_t ea_ = D_DI_PRINT; uint16_t t_ = RD16(DS, ea_); ADD16(t_, AX, FL_NONE); WR16(DS, ea_, t_); }	/* ADD di_print,ax */
