	if (C_NE) goto L_RETTA_NUDA;	/* JNE retta_nuda */
	CL = RD8(DS, D_PLAYERS);	/* MOV cl,players */
	XOR8(CH, CH, FL_NONE);	/* XOR ch,ch */
	SI = D_LAST_TEXT;	/* MOV si,offset last_text */
