	PUSH16(SEG_DATA);	/* PUSH data */
	ES = POP16();	/* POP es */
	WR8(CS, D_ALLA_GLADA, 0);	/* MOV cs:alla_glada,false */
L_READ_NUFFROR:;
	x_lodsw(DS);	/* LODSW */
