	TAILPTR(x_dispatch(CS, RD16(DS, (uint16_t)(BX))));	/* JMP [BX] */
L_THIS_ONE:;
	AL = RD8(DS, D_PLAYER);	/* MOV AL,PLAYER */
	ADD8(AL, 0x37, FL_ALL);	/* ADD AL,'7' */
	WR8(DS, (uint16_t)(D_PLAYERSTEXT + 7), AL);	/* MOV PLAYERSTEXT[7],AL */
