	DI = D_BONUSSIFFRORNA;	/* MOV DI,OFFSET BONUSSIFFRORNA */
	CALLN(t4_f_ADDSCOREBCD, 0x1028);	/* CALL ADDSCOREBCD */
	CX = POP16();	/* POP CX */
