	WR8(DS, (uint16_t)(D_BONUS_X_TEXT + 9), 0x37);	/* MOV BONUS_X_TEXT[9],0+'7' */
	AL = RD8(DS, D_BONUS_X);	/* MOV AL,BONUS_X */
	ADD8(AL, 0x37, FL_NONE);	/* ADD AL,'7' */
	CMP8(AL, 0x41, FL_ALL);	/* CMP AL,10+'7' */
	if (C_AE) goto L_ITS10;	/* JNB ITS10 */
	WR8(DS, (uint16_t)(D_BONUS_X_TEXT + 8), AL);	/* MOV BONUS_X_TEXT[8],AL */
	WR8(DS, (uint16_t)(D_BONUS_X_TEXT + 9), 0x20);	/* MOV BONUS_X_TEXT[9],' ' */
L_ITS10:;
	ES = POP16();	/* POP ES */
	BX = POP16();	/* POP BX */
	WR16(DS, D_SISA, 1);	/* MOV SISA,1 */
	WR16(DS, D_DOTRUT, C_WAITRUT);	/* MOV DOTRUT,OFFSET WAITRUT */
