void t4_f_SHOWTOWER(void)
{
	PUSH16(0xA000);	/* PUSH 0a000h */
	ES = POP16();	/* POP es */
	PUSH16(SEG_ANIM08SEG);	/* PUSH anim08seg */
	DS = POP16();	/* POP ds */
	DI = 0xA8;	/* MOV di,sw/4*2 */
	DX = 0;	/* MOV dx,0 */
	AX = 0x28;	/* MOV ax,320/8 */
	MUL16(CX);	/* MUL cx */
	SI = D_ANIM08;	/* MOV si,offset anim08 */
	ADD16(SI, AX, FL_NONE);	/* ADD si,ax */
	BL = 0x80;	/* MOV bl,10000000b */
	BH = 8;	/* MOV bh,00001000b */
	CX = 2;	/* MOV cx,2 */
L_TWO:;
	PUSH16(CX);	/* PUSH cx */
	PUSH16(SI);	/* PUSH si */
	PUSH16(DI);	/* PUSH di */
	PUSH16(BX);	/* PUSH bx */
	SHR8(BH, 1, FL_NONE);	/* SHR bh,1 */
	XOR8(BH, 5, FL_NONE);	/* XOR bh,101b */
	DX = 0x3C4;	/* MOV dx,3c4h */
	AH = BH;	/* MOV ah,bh */
	AL = 2;	/* MOV al,2 */
	OUT16(DX, AX);	/* OUT dx,ax */
	BX = POP16();	/* POP bx */
	CX = 0x10;	/* MOV cx,16 */
L_PUT_KLL:;
	PUSH16(CX);	/* PUSH cx */
	CX = 0x28;	/* MOV cx,320/8 */
L_PUT_BITS:;
	DL = RD8(DS, (uint16_t)(SI));	/* MOV dl,[si] */
	INC16(SI, FL_NONE);	/* INC si */
	TEST8(DL, BL, (FL_Z));	/* TEST dl,bl */
	if (C_E) goto L_GULAN;	/* JE gulan */
	AL = 0x4F;	/* MOV al,matrixlo */
	x_stosb();	/* STOSB */
	goto L_OVERIT_EHRM;	/* JMP overit_ehrm */
L_GULAN:;
	AL = 0xE7;	/* MOV al,matrixhi */
	x_stosb();	/* STOSB */
L_OVERIT_EHRM:;
	TEST8(DL, BH, (FL_Z));	/* TEST dl,bh */
	if (C_E) goto L_GULAN2;	/* JE gulan2 */
	AL = 0x4F;	/* MOV al,matrixlo */
	x_stosb();	/* STOSB */
	goto L_OVERIT_EHRM2;	/* JMP overit_ehrm2 */
L_GULAN2:;
	AL = 0xE7;	/* MOV al,matrixhi */
	x_stosb();	/* STOSB */
L_OVERIT_EHRM2:;
	CX = (uint16_t)(CX - 1);	/* LOOP put_bits */
	if (CX != 0) { X_POLL(); goto L_PUT_BITS; }
	CX = POP16();	/* POP cx */
	ADD16(DI, 0x58, FL_NONE);	/* ADD di,sw/4+(sw-320)/4 */
	CX = (uint16_t)(CX - 1);	/* LOOP put_kll */
	if (CX != 0) { X_POLL(); goto L_PUT_KLL; }
	DI = POP16();	/* POP di */
	SI = POP16();	/* POP si */
	CX = POP16();	/* POP cx */
	SHR16(BX, 2, FL_ALL);	/* SHR bx,2 */
	CX = (uint16_t)(CX - 1);	/* LOOP two */
	if (CX != 0) { X_POLL(); goto L_TWO; }
	PUSH16(SEG_DATA);	/* PUSH data */
	DS = POP16();	/* POP ds */
	RETURN_NEAR(0);	/* RETN */
}

