	AX = 5;	/* MOV AX,5 */
	IMUL16(RD16(DS, D_PLUSHAST));	/* IMUL PLUSHAST */
	CX = 6;	/* MOV CX,6 */
	IDIV16(CX);	/* IDIV CX */
	WR16(DS, D_PLUSHAST, AX);	/* MOV PLUSHAST,AX */
	AX = 5;	/* MOV AX,5 */
	IMUL16(RD16(DS, D_BUMPERPOWER));	/* IMUL bumperpower */
	CX = 6;	/* MOV CX,6 */
	IDIV16(CX);	/* IDIV CX */
	WR16(DS, D_BUMPERPOWER, AX);	/* MOV bumperpower,AX */
	AX = 5;	/* MOV AX,5 */
