	x_lodsb(DS);	/* LODSB */
	CMP8(AL, 0x24, FL_ALL);	/* CMP al,'$' */
	if (C_E) goto L_FOUND;	/* JE found */
	CMP16(DX, RD16(DS, D_CHEATPEKARE), (FL_C));	/* CMP dx,cheatpekare */
	if (C_AE) goto L_NOWNAAAATING;	/* JAE nownaaaating */
	INC16(DX, FL_NONE);	/* INC dx */
	CMP8(AL, RD8(DS, (uint16_t)(DI)), (FL_Z));	/* CMP al,[di] */
	if (C_NE) goto L_NOTFOUND;	/* JNE notfound */
	INC16(DI, FL_NONE);	/* INC di */
	{ X_POLL(); goto L_NEXTTEST; }	/* JMP nexttest */
L_NOWNAAAATING:;
	WR8(DS, D_DONT_KNOW_YET, 0xFF);	/* MOV dont_know_yet,true */
L_NOTFOUND:;
	x_lodsb(DS);	/* LODSB */
	CMP8(AL, 0x24, (FL_Z));	/* CMP al,'$' */
	if (C_E) { X_POLL(); goto L_CHECKIT; }	/* JE checkit */
	{ X_POLL(); goto L_NOTFOUND; }	/* JMP notfound */
L_ENDOFCHEATS:;
	{ uint8_t t_ = RD8(DS, D_DONT_KNOW_YET); CMP8(t_, 0xFF, FL_ALL); }	/* CMP dont_know_yet,true */
	if (C_E) goto L_NOREZZA_OFIT;	/* JE norezza_ofit */
	WR16(DS, D_CHEATPEKARE, 1);	/* MOV cheatpekare,1 */
	CX = 0xB;	/* MOV cx,11 */
	DI = D_CHEATINPUT;	/* MOV di,offset cheatinput */
	AL = RD8(DS, D_DENSOMSPARHANHAR);	/* MOV al,densomsparhanhar */
	x_stosb();	/* STOSB */
	AL = 0x20;	/* MOV al,' ' */
	x_rep_stosb();	/* STOSB */
L_NOREZZA_OFIT:;
	RETURN_NEAR(0);	/* RETN */
L_NOVALIDKEY:;
	RETURN_NEAR(0);	/* RETN */
L_FOUND:;
	WR16(DS, D_CHEATPEKARE, 0);	/* MOV cheatpekare,0 */
	CALLPTR(x_dispatch(CS, BX), 0x1269);	/* CALL bx */
	RETURN_NEAR(0);	/* RETN */
