	CMP8(AL, 0x57, FL_ALL);	/* CMP AL,57H */
	if (C_NE) goto L_NOTF11;	/* JNE NOTF11 */
	WR8(DS, D_FFLAG, 0xB);	/* MOV FFLAG,11 */
