	CMP8(AL, 0x58, FL_ALL);	/* CMP AL,58H */
	if (C_NE) goto L_NOTF12;	/* JNE NOTF12 */
	WR8(DS, D_FFLAG, 0xC);	/* MOV FFLAG,12 */
	goto L_KEYDONE;	/* JMP KEYDONE */
L_NOTF12:;
	CMP8(AL, 0x2A, (FL_Z));	/* CMP AL,2AH */
	if (C_E) goto L_DSSK;	/* JE DSSK */
	CMP8(AL, 0x38, (FL_Z));	/* CMP AL,38H */
	if (C_E) goto L_DSSK;	/* JE DSSK */
	CMP8(AL, 0x1D, (FL_Z));	/* CMP AL,1DH */
	if (C_E) goto L_DSSK;	/* JE DSSK */
	goto L_NOTLSDN;	/* JMP SHORT NOTLSDN */
L_DSSK:;
	{ uint8_t t_ = RD8(DS, D_SHIFTKEYS); TEST8(t_, 2, (FL_Z)); }	/* TEST SHIFTKEYS,10B */
	if (C_NE) goto L_NOTLSDN;	/* JNZ NOTLSDN */
	{ uint16_t ea_ = D_SHIFTKEYS; uint8_t t_ = RD8(DS, ea_); OR8(t_, 2, FL_NONE); WR8(DS, ea_, t_); }	/* OR SHIFTKEYS,10B */
	WR8(DS, D_SHIFTPRESSED, 0xFF);	/* MOV SHIFTPRESSED,TRUE */
