	BH = 0;	/* MOV bh,0 */
	CL = RD8(DS, D_SFLIPPUPP);	/* MOV CL,sflippupp+0 */
	BL = RD8(DS, (uint16_t)(D_SFLIPPUPP + 1));	/* MOV BL,sflippupp+1 */
	DL = RD8(DS, (uint16_t)(D_SFLIPPUPP + 3));	/* MOV DL,sflippupp+3 */
	INC8(DL, (FL_Z | FL_S | FL_O | FL_P | FL_A));	/* INC DL */
	AL = 0x11;	/* MOV AL,17 */
	x_int(0x66);	/* INT 66H */
	goto L_KEYDONE;	/* JMP KEYDONE */
L_NOTLSDN:;
	CMP8(AL, 0x36, (FL_Z));	/* CMP AL,36H */
	if (C_E) goto L_DSSKR;	/* JE DSSKR */
	goto L_NOTRSDN;	/* JMP SHORT NOTRSDN */
L_DSSKR:;
	{ uint8_t t_ = RD8(DS, D_SHIFTKEYS); TEST8(t_, 1, (FL_Z)); }	/* TEST shiftkeys,1 */
	if (C_NE) goto L_NOTRSDN;	/* JNZ notrsdn */
	{ uint16_t ea_ = D_SHIFTKEYS; uint8_t t_ = RD8(DS, ea_); OR8(t_, 1, FL_NONE); WR8(DS, ea_, t_); }	/* OR SHIFTKEYS,1 */
	WR8(DS, D_SHIFTPRESSED, 0xFF);	/* MOV SHIFTPRESSED,TRUE */
	{ uint8_t t_ = RD8(DS, D_ALLOWFLIP); CMP8(t_, 0, FL_ALL); }	/* CMP allowflip,false */
	if (C_E) goto L_KEYDONE;	/* JE keydone */
	BH = 0;	/* MOV bh,0 */
	CL = RD8(DS, D_SFLIPPUPP);	/* MOV CL,sflippupp+0 */
	BL = RD8(DS, (uint16_t)(D_SFLIPPUPP + 1));	/* MOV BL,sflippupp+1 */
	DL = RD8(DS, (uint16_t)(D_SFLIPPUPP + 3));	/* MOV DL,sflippupp+3 */
	INC8(DL, (FL_Z | FL_S | FL_O | FL_P | FL_A));	/* INC DL */
	AL = 0x11;	/* MOV AL,17 */
	x_int(0x66);	/* INT 66H */
	goto L_KEYDONE;	/* JMP KEYDONE */
L_NOTRSDN:;
	CMP8(AL, 0xB6, (FL_Z));	/* CMP AL,36H+80H */
	if (C_E) goto L_DSSKR2;	/* JE DSSKR2 */
	goto L_NOTRSUP;	/* JMP SHORT NOTRSUP */
L_DSSKR2:;
	{ uint16_t ea_ = D_SHIFTKEYS; uint8_t t_ = RD8(DS, ea_); AND8(t_, 0xFE, FL_ALL); WR8(DS, ea_, t_); }	/* AND SHIFTKEYS,0FEH */
	goto L_KEYDONE;	/* JMP KEYDONE */
L_NOTRSUP:;
