	goto L_KEYDONE;	/* JMP KEYDONE */
L_NOTLSUP:;
	CMP8(AL, 0x39, (FL_Z));	/* CMP AL,57 */
	if (C_NE) goto L_NOTSPC;	/* JNE NOTSPC */
