L_NOTSPC:;
	CMP8(AL, 0xB9, FL_ALL);	/* CMP AL,57+80H */
	if (C_NE) goto L_NOTSPCU;	/* JNE NOTSPCU */
	WR8(DS, D_TILTKEY, 0);	/* MOV TILTKEY,FALSE */
	WR8(CS, D_TILTKEY2, 0);	/* MOV cs:TILTKEY2,FALSE */
	goto L_KEYDONE;	/* JMP KEYDONE */
L_NOTSPCU:;
	CMP8(AL, 2, FL_ALL);	/* CMP AL,2 */
	if (C_NE) goto L_NOT2;	/* JNE NOT2 */
	CLI();	/* CLI */
	WR8(DS, D_INTERRUPTS_ON, 0);	/* MOV INTERRUPTS_ON,FALSE */
	PUSH16(0xA000);	/* PUSH 0A000H */
	ES = POP16();	/* POP ES */
	AX = 0xD;	/* MOV AX,0DH */
	x_int(0x10);	/* INT 10H */
	SI = 0;	/* MOV SI,0 */
	PUSH16(SEG_MASK2_2);	/* PUSH MASK2_2 */
	DS = POP16();	/* POP DS */
	CX = 0x1F40;	/* MOV CX,200*40 */
	DI = 0;	/* MOV DI,0 */
	x_rep_movsb(DS);	/* MOVSB */
	CLI();	/* CLI */
	DX = 0x3D4;	/* MOV dx,3d4h */
	AX = 0xC;	/* MOV ax,0ch */
	OUT16(DX, AX);	/* OUT dx,ax */
	INC8(AL, (FL_Z | FL_S | FL_O | FL_P | FL_A));	/* INC al */
	OUT16(DX, AX);	/* OUT dx,ax */
	for (;;) { X_POLL(); }	/* JMP $ */
L_NOT2:;
	CMP8(AL, 0x48, FL_ALL);	/* CMP AL,72 */
	if (C_NE) goto L_NOTPUP;	/* JNE NOTPUP */
	WR16(DS, D_Y_HAST, 0xFC00);	/* MOV Y_HAST,-1*PILHAST */
