	goto L_KEYDONE;	/* JMP KEYDONE */
L_NOTPUP:;
	CMP8(AL, 0x4B, FL_ALL);	/* CMP AL,75 */
	if (C_NE) goto L_NOTPL;	/* JNE NOTPL */
	WR16(DS, D_X_HAST, 0xFC00);	/* MOV X_HAST,-1*PILHAST */
	WR16(DS, D_Y_HAST, 0);	/* MOV Y_HAST,0 */
	goto L_KEYDONE;	/* JMP KEYDONE */
L_NOTPL:;
	CMP8(AL, 0x4D, FL_ALL);	/* CMP AL,77 */
	if (C_NE) goto L_NOTPR;	/* JNE NOTPR */
	WR16(DS, D_X_HAST, 0x400);	/* MOV X_HAST,1*PILHAST */
