	goto L_KEYDONE;	/* JMP KEYDONE */
L_NOTPR:;
	CMP8(AL, 0x50, FL_ALL);	/* CMP AL,80 */
	if (C_NE) goto L_NOTPDN;	/* JNE NOTPDN */
