L_NOTPDN:;
L_KEYDONE:;
	DS = POP16();	/* POP DS */
	POPA();	/* POPA */
	RETURN_IRET();	/* IRET */
L_DOE0:;
	WR8(CS, D_E0, 0);	/* MOV CS:E0,FALSE */
	{ uint8_t t_ = RD8(DS, D_DEMOMODE); CMP8(t_, 0xFF, (FL_Z)); }	/* CMP DEMOMODE,TRUE */
