	{ X_POLL(); goto L_KEYDONE; }	/* JMP KEYDONE */
L_DOE0_DEMO:;
	CMP8(AL, 0x49, (FL_Z));	/* CMP AL,49H */
	if (C_NE) goto L_NOT_PGUP2;	/* JNE NOT_PGUP2 */
	{ uint16_t ea_ = D_SHIFTKEYS; uint8_t t_ = RD8(DS, ea_); AND8(t_, 0xFB, FL_ALL); WR8(DS, ea_, t_); }	/* AND SHIFTKEYS,11111011B */
