	{ uint16_t t_ = RD16(DS, D_RULL_POS); CMP16(t_, AX, FL_ALL); }	/* CMP rull_pos,ax */
	if (C_E) { X_POLL(); TAIL(t4_f_REZZETA); }	/* JE rezzeta */
