	{ uint16_t ea_ = D_CLEAR_BOX_START; uint16_t t_ = RD16(DS, ea_); ADD16(t_, 0x540, FL_ALL); WR16(DS, ea_, t_); }	/* ADD clear_box_start,8*2*sw/4 */
	WR16(DS, D_CLEAR_BOX_BREDD, 0x50);	/* MOV clear_box_bredd,320/4 */
