	{ uint16_t ea_ = D_CLEAR_BOX_START; uint16_t t_ = RD16(DS, ea_); ADD16(t_, 0x7E0, FL_ALL); WR16(DS, ea_, t_); }	/* ADD clear_box_start,12*2*sw/4 */
