	if (C_BE) goto L_DELTA_ANIMERA;	/* JBE DELTA_ANIMERA */
	AX = POP16();	/* POP AX */
	AX = CX;	/* MOV AX,CX */
	SUB16(AX, 9, FL_NONE);	/* SUB AX,9 */
	PUSH16(AX);	/* PUSH AX */
	CX = 9;	/* MOV CX,9 */
L_DELTA_ANIMERA:;
	PUSH16(CX);	/* PUSH CX */
