	if (C_E) goto L_NOTTHISONE;	/* JZ NOTTHISONE */
	{ uint8_t t_ = RD8(DS, (uint16_t)(BX + 0x1)); CMP8(t_, 0, FL_ALL); }	/* CMP [BX].FLASHCOUNTER,0 */
	if (C_NE) goto L_NOTZEROISIT;	/* JNZ NOTZEROISIT */
L_GOTOZERO:;
	PUSH16(BX);	/* PUSH BX */
	BL = RD8(DS, (uint16_t)(BX));	/* MOV BL,[BX].LNUM */
	CALLN(t4_f_DOLON, 0x1FF3);	/* CALL DOLON */
	BX = POP16();	/* POP BX */
	goto L_LETSINCIT;	/* JMP LETSINCIT */
L_NOTZEROISIT:;
	AL = RD8(DS, (uint16_t)(BX + 0x2));	/* MOV AL,[BX].TURNOFF */
	{ uint8_t t_ = RD8(DS, (uint16_t)(BX + 0x1)); CMP8(t_, AL, FL_ALL); }	/* CMP [BX].FLASHCOUNTER,AL */
	if (C_NE) goto L_NOTOFFISIT;	/* JNE NOTOFFISIT */
	PUSH16(BX);	/* PUSH BX */
	BL = RD8(DS, (uint16_t)(BX));	/* MOV BL,[BX].LNUM */
	CALLN(t4_f_DOLOFF, 0x1FFB);	/* CALL DOLOFF */
	BX = POP16();	/* POP BX */
	goto L_LETSINCIT;	/* JMP LETSINCIT */
L_NOTOFFISIT:;
	AL = RD8(DS, (uint16_t)(BX + 0x3));	/* MOV AL,[BX].RESETFC */
	{ uint8_t t_ = RD8(DS, (uint16_t)(BX + 0x1)); CMP8(t_, AL, FL_ALL); }	/* CMP [BX].FLASHCOUNTER,AL */
	if (C_NE) goto L_NOTRESETISIT;	/* JNE NOTRESETISIT */
	WR8(DS, (uint16_t)(BX + 0x1), 0);	/* MOV [BX].FLASHCOUNTER,0 */
	{ X_POLL(); goto L_GOTOZERO; }	/* JMP GOTOZERO */
L_NOTRESETISIT:;
L_LETSINCIT:;
	{ uint16_t ea_ = (uint16_t)(BX + 0x1); uint8_t t_ = RD8(DS, ea_); INC8(t_, FL_NONE); WR8(DS, ea_, t_); }	/* INC [BX].FLASHCOUNTER */
L_NOTTHISONE:;
	ADD16(BX, 4, FL_NONE);	/* ADD BX,SIZE FLASHSTRUC */
