	BL = AL;	/* MOV BL,AL */
	XOR8(BH, BH, FL_NONE);	/* XOR BH,BH */
	DEC16(BX, FL_NONE);	/* DEC BX */
	SHL16(BX, 1, FL_ALL);	/* SHL BX,1 */
