	if (C_NE) goto L_DONT_LOOSE_BALL;	/* JNE DONT_LOOSE_BALL */
	{ uint8_t t_ = RD8(DS, D_LOOSING); CMP8(t_, 0xFF, FL_ALL); }	/* CMP LOOSING,TRUE */
