	ADD16(SI, RD16(DS, D_FLIPLINESIZE), FL_NONE);	/* ADD SI,FLIPLINESIZE */
	{ uint8_t t_ = RD8(ES, (uint16_t)(SI)); TEST8(t_, DL, (FL_Z)); }	/* TEST BYTE PTR ES:[SI],DL */
	SI = POP16();	/* POP SI */
	if (C_E) goto L_NOTB1;	/* JZ NOTB1 */
	OR8(AL, 2, FL_NONE);	/* OR AL,10B */
L_NOTB1:;
	PUSH16(SI);	/* PUSH SI */
	ADD16(SI, RD16(DS, D_FLIPLINESIZE), FL_NONE);	/* ADD SI,FLIPLINESIZE */
	ADD16(SI, RD16(DS, D_FLIPLINESIZE), FL_NONE);	/* ADD SI,FLIPLINESIZE */
	{ uint8_t t_ = RD8(ES, (uint16_t)(SI)); TEST8(t_, DL, FL_ALL); }	/* TEST BYTE PTR ES:[SI],DL */
