{
	PUSH16(ES);	/* PUSH ES */
	PUSH16(DS);	/* PUSH DS */
	PUSH16(0xA000);	/* PUSH 0A000H */
	ES = POP16();	/* POP ES */
	PUSH16(ES);	/* PUSH ES */
	DS = POP16();	/* POP DS */
	DX = 0x3C4;	/* MOV DX,3C4H */
	AX = 0xF02;	/* MOV AX,0F02H */
	OUT16(DX, AX);	/* OUT DX,AX */
	DX = 0x3CE;	/* MOV DX,3CEH */
	AX = 0x4105;	/* MOV AX,4105H */
	OUT16(DX, AX);	/* OUT DX,AX */
	CX = 0x35;	/* MOV CX,53 */
L_COPPYA:;
	PUSH16(CX);	/* PUSH CX */
	CX = 0x14;	/* MOV CX,20 */
	x_rep_movsb(DS);	/* MOVSB */
	CX = POP16();	/* POP CX */
	ADD16(DI, 0x40, FL_NONE);	/* ADD DI,BPL-20 */
	ADD16(SI, 0x40, FL_ALL);	/* ADD SI,BPL-20 */
	CX = (uint16_t)(CX - 1);	/* LOOP COPPYA */
	if (CX != 0) { X_POLL(); goto L_COPPYA; }
	AX = 0x4005;	/* MOV AX,4005H */
	OUT16(DX, AX);	/* OUT DX,AX */
	DS = POP16();	/* POP DS */
	ES = POP16();	/* POP ES */
	RETURN_NEAR(0);	/* RETN */
}

void t4_f_CMPFLIPBOX(void)
{
	WR16(CS, D_DIFCNT, 0);	/* MOV CS:DIFCNT,0 */
	WR16(CS, D_ORGDI, DI);	/* MOV CS:ORGDI,DI */
	PUSH16(DS);	/* PUSH DS */
	PUSH16(SI);	/* PUSH SI */
	PUSH16(SEG_DATAFLIP);	/* PUSH DATAFLIP */
	DS = POP16();	/* POP DS */
	PUSH16(0xA000);	/* PUSH 0A000H */
	ES = POP16();	/* POP ES */
	DX = 0x3C4;	/* MOV DX,3C4H */
	AX = 0xF02;	/* MOV AX,0F02H */
	OUT16(DX, AX);	/* OUT DX,AX */
	DX = 0x3CE;	/* MOV DX,3CEH */
	AX = 0x4105;	/* MOV AX,4105H */
	OUT16(DX, AX);	/* OUT DX,AX */
	AX = 4;	/* MOV AX,4 */
	CX = 0x35;	/* MOV CX,53 */
L_CMPR:;
	PUSH16(CX);	/* PUSH CX */
	CX = 0x10;	/* MOV CX,16 */
L_CHECK4:;
	OUT16(DX, AX);	/* OUT DX,AX */
	BL = RD8(ES, (uint16_t)(DI + BP));	/* MOV BL,ES:[DI+BP] */
	CMP8(BL, RD8(ES, (uint16_t)(DI)), (FL_Z));	/* CMP BL,ES:[DI] */
	if (C_E) goto L_LIKA;	/* JE LIKA */
	SUB16(DI, RD16(CS, D_ORGDI), FL_NONE);	/* SUB DI,CS:ORGDI */
	WR16(DS, (uint16_t)(SI + 0x12), DI);	/* MOV DS:[SI+2*9],DI */
	ADD16(DI, RD16(CS, D_ORGDI), (FL_C));	/* ADD DI,CS:ORGDI */
	{ uint16_t ea_ = D_DIFCNT; uint16_t t_ = RD16(CS, ea_); INC16(t_, (FL_Z | FL_S | FL_O | FL_P | FL_A)); WR16(CS, ea_, t_); }	/* INC CS:DIFCNT */
	PUSH16(DI);	/* PUSH DI */
	CALLN(t4_f_LOOK4BLOCK, 0x2753);	/* CALL LOOK4BLOCK */
	if (C_B) goto L_COULDNTFIND;	/* JC COULDNTFIND */
	WR16(DS, (uint16_t)(SI + 0x14), DI);	/* MOV DS:[SI+2*9+2],DI */
	ADD16(SI, 4, FL_NONE);	/* ADD SI,4 */
	DI = POP16();	/* POP DI */
	goto L_NEXT4;	/* JMP SHORT NEXT4 */
L_COULDNTFIND:;
	BL = RD8(ES, (uint16_t)(DI));	/* MOV BL,ES:[DI] */
	DI = RD16(CS, D_DIFPTR);	/* MOV DI,CS:DIFPTR */
	WR16(DS, (uint16_t)(SI + 0x14), DI);	/* MOV DS:[SI+2*9+2],DI */
	ADD16(SI, 4, FL_NONE);	/* ADD SI,4 */
	x_stosb();	/* STOSB */
	WR16(CS, D_DIFPTR, DI);	/* MOV CS:DIFPTR,DI */
	DI = POP16();	/* POP DI */
	goto L_NEXT4;	/* JMP SHORT NEXT4 */
L_LIKA:;
	INC8(AH, FL_NONE);	/* INC AH */
	AND8(AH, 3, (FL_Z));	/* AND AH,11B */
	if (C_NE) { X_POLL(); goto L_CHECK4; }	/* JNZ CHECK4 */
L_NEXT4:;
	AH = 0;	/* MOV AH,0 */
	INC16(DI, FL_NONE);	/* INC DI */
	CX = (uint16_t)(CX - 1);	/* LOOP CHECK4 */
	if (CX != 0) { X_POLL(); goto L_CHECK4; }
	ADD16(DI, 0x44, FL_ALL);	/* ADD DI,BPL-16 */
	CX = POP16();	/* POP CX */
	CX = (uint16_t)(CX - 1);	/* LOOP CMPR */
	if (CX != 0) { X_POLL(); goto L_CMPR; }
	SI = POP16();	/* POP SI */
	PUSH16(RD16(CS, D_DIFCNT));	/* PUSH CS:DIFCNT */
	WR16(DS, (uint16_t)(SI), POP16());	/* POP DS:[SI] */
	DS = POP16();	/* POP DS */
	AX = 0x4005;	/* MOV AX,4005H */
	OUT16(DX, AX);	/* OUT DX,AX */
	RETURN_NEAR(0);	/* RETN */
}

void t4_f_LOOK4BLOCK(void)
{
	PUSH16(AX);	/* PUSH AX */
	PUSH16(BX);	/* PUSH BX */
	PUSH16(CX);	/* PUSH CX */
	PUSH16(SI);	/* PUSH SI */
	AX = 4;	/* MOV AX,4 */
	OUT16(DX, AX);	/* OUT DX,AX */
	BL = RD8(ES, (uint16_t)(DI));	/* MOV BL,ES:[DI] */
	INC8(AH, FL_NONE);	/* INC AH */
	OUT16(DX, AX);	/* OUT DX,AX */
	BH = RD8(ES, (uint16_t)(DI));	/* MOV BH,ES:[DI] */
	INC8(AH, FL_NONE);	/* INC AH */
	OUT16(DX, AX);	/* OUT DX,AX */
	CL = RD8(ES, (uint16_t)(DI));	/* MOV CL,ES:[DI] */
	INC8(AH, FL_NONE);	/* INC AH */
	OUT16(DX, AX);	/* OUT DX,AX */
	CH = RD8(ES, (uint16_t)(DI));	/* MOV CH,ES:[DI] */
	PUSH16(SEG_DATA);	/* PUSH data */
	DS = POP16();	/* POP ds */
	SI = 0xD4F4;	/* MOV SI,GFXADR_FOR_FLIP_ANIM_DATA */
	PUSH16(SEG_DATAFLIP);	/* PUSH dataflip */
	DS = POP16();	/* POP ds */
L_NEXTBLOCK:;
	XOR8(AH, AH, FL_NONE);	/* XOR AH,AH */
	OUT16(DX, AX);	/* OUT DX,AX */
	{ uint8_t t_ = RD8(ES, (uint16_t)(SI)); CMP8(t_, BL, (FL_Z)); }	/* CMP BYTE PTR ES:[SI],BL */
	if (C_NE) goto L_NOTTHISBLOCK;	/* JNE NOTTHISBLOCK */
	INC8(AH, FL_NONE);	/* INC AH */
	OUT16(DX, AX);	/* OUT DX,AX */
	{ uint8_t t_ = RD8(ES, (uint16_t)(SI)); CMP8(t_, BH, (FL_Z)); }	/* CMP BYTE PTR ES:[SI],BH */
	if (C_NE) goto L_NOTTHISBLOCK;	/* JNE NOTTHISBLOCK */
	INC8(AH, FL_NONE);	/* INC AH */
	OUT16(DX, AX);	/* OUT DX,AX */
	{ uint8_t t_ = RD8(ES, (uint16_t)(SI)); CMP8(t_, CL, (FL_Z)); }	/* CMP BYTE PTR ES:[SI],CL */
	if (C_NE) goto L_NOTTHISBLOCK;	/* JNE NOTTHISBLOCK */
	INC8(AH, FL_NONE);	/* INC AH */
	OUT16(DX, AX);	/* OUT DX,AX */
	{ uint8_t t_ = RD8(ES, (uint16_t)(SI)); CMP8(t_, CH, (FL_Z | FL_S | FL_O | FL_P | FL_A)); }	/* CMP BYTE PTR ES:[SI],CH */
	if (C_NE) goto L_NOTTHISBLOCK;	/* JNE NOTTHISBLOCK */
	DI = SI;	/* MOV DI,SI */
	CLC();	/* CLC */
L_UNIQUE:;
	SI = POP16();	/* POP SI */
	CX = POP16();	/* POP CX */
	BX = POP16();	/* POP BX */
	AX = POP16();	/* POP AX */
	RETURN_NEAR(0);	/* RETN */
L_NOTTHISBLOCK:;
	INC16(SI, FL_NONE);	/* INC SI */
	CMP16(SI, RD16(CS, D_DIFPTR), FL_ALL);	/* CMP SI,CS:DIFPTR */
	if (C_B) { X_POLL(); goto L_NEXTBLOCK; }	/* JB NEXTBLOCK */
	STC();	/* STC */
	{ X_POLL(); goto L_UNIQUE; }	/* JMP UNIQUE */
}

void t4_f_DELTANIM(void)
{
	AX = DI;	/* MOV AX,DI */
L_DODELTA:;
	DI = RD16(DS, (uint16_t)(BX));	/* MOV DI,[BX] */
	ADD16(DI, AX, FL_NONE);	/* ADD DI,AX */
	SI = RD16(DS, (uint16_t)(BX + 0x2));	/* MOV SI,[BX+2] */
	x_movsb(ES);	/* MOVSB */
	ADD16(BX, 4, FL_ALL);	/* ADD BX,4 */
	CX = (uint16_t)(CX - 1);	/* LOOP DODELTA */
	if (CX != 0) { X_POLL(); goto L_DODELTA; }
	RETURN_NEAR(0);	/* RETN */
}

void t4_f_INIT_SIN(void)
{
	SI = D_SIN;	/* MOV SI,OFFSET SIN */
	CX = 0xA00;	/* MOV CX,2048+2048/4 */
L_XCHGSIN:;
	x_lodsb(DS);	/* LODSB */
	AH = AL;	/* MOV AH,AL */
	x_lodsb(DS);	/* LODSB */
	WR16(DS, (uint16_t)(SI + 0xFFFE), AX);	/* MOV DS:[SI-2],AX */
	CX = (uint16_t)(CX - 1);	/* LOOP XCHGSIN */
	if (CX != 0) { X_POLL(); goto L_XCHGSIN; }
	RETURN_NEAR(0);	/* RETN */
}

void t4_f_BREDDA_MASK(void)
{
	PUSH16(DS);	/* PUSH DS */
	PUSH16(SEG_HIDDEN1);	/* PUSH HIDDEN1 */
	DS = POP16();	/* POP DS */
	PUSH16(DS);	/* PUSH DS */
	ES = POP16();	/* POP ES */
	DI = D_HIDDA;	/* MOV DI,OFFSET HIDDA */
	SI = D_HID1;	/* MOV SI,OFFSET HID1 */
	CALLN(t4_f_BREDDA, 0x27C2);	/* CALL BREDDA */
	PUSH16(SEG_HIDDEN2);	/* PUSH HIDDEN2 */
	DS = POP16();	/* POP DS */
	PUSH16(DS);	/* PUSH DS */
	ES = POP16();	/* POP ES */
	DI = D_HIDDA2;	/* MOV DI,OFFSET HIDDA2 */
	SI = D_HID2;	/* MOV SI,OFFSET HID2 */
	CALLN(t4_f_BREDDA, 0x27C9);	/* CALL BREDDA */
	DS = POP16();	/* POP DS */
	RETURN_NEAR(0);	/* RETN */
}

void t4_f_BREDDA(void)
{
	CX = 0x240;	/* MOV CX,576 */
L_LINE1:;
	PUSH16(CX);	/* PUSH CX */
	CX = 0x28;	/* MOV CX,40 */
	x_rep_movsb(DS);	/* MOVSB */
	ADD16(DI, 2, FL_ALL);	/* ADD DI,2 */
	CX = POP16();	/* POP CX */
	CX = (uint16_t)(CX - 1);	/* LOOP LINE1 */
	if (CX != 0) { X_POLL(); goto L_LINE1; }
	RETURN_NEAR(0);	/* RETN */
}

